const orphanGloballyStaleArtifactNodes = `-- name: OrphanGloballyStaleArtifactNodes :many
WITH stale AS (
    SELECT artifact_hash, node_id FROM foghorn.artifact_nodes
    WHERE is_orphaned = false AND last_seen_at < NOW() - INTERVAL '15 minutes'
    ORDER BY last_seen_at
    LIMIT 500
    FOR UPDATE SKIP LOCKED
)
UPDATE foghorn.artifact_nodes an SET is_orphaned = true
FROM stale
WHERE an.artifact_hash = stale.artifact_hash AND an.node_id = stale.node_id
  AND an.is_orphaned = false
  AND an.last_seen_at < NOW() - INTERVAL '15 minutes'
RETURNING an.artifact_hash, an.node_id, an.role
`

type OrphanGloballyStaleArtifactNodesRow struct {
	ArtifactHash string `db:"artifact_hash" json:"artifact_hash"`
	NodeID       string `db:"node_id" json:"node_id"`
	Role         string `db:"role" json:"role"`
}

func (q *Queries) OrphanGloballyStaleArtifactNodes(ctx context.Context) ([]OrphanGloballyStaleArtifactNodesRow, error) {
	rows, err := q.db.QueryContext(ctx, orphanGloballyStaleArtifactNodes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OrphanGloballyStaleArtifactNodesRow{}
	for rows.Next() {
		var i OrphanGloballyStaleArtifactNodesRow
		if err := rows.Scan(&i.ArtifactHash, &i.NodeID, &i.Role); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

